-- Add the Teemo - Scout (GG EZ) card in English and Korean, and label the Chinese one. Safe to run more than once.
update promo_items set data = data || jsonb_build_object('nm','Teemo - Scout (GG EZ)') where id = 'item-84';
insert into promo_items (id, r, data)
select 'item-10660', 10660, $j${"r": 10660, "id": "item-10660", "cat": "PROMO", "nm": "Teemo - Scout (GG EZ)", "la": "English", "ev": "Nexus Night Promo", "se": "OGN", "ty": "Card", "cn": "197b", "ra": "Overnumber/Alternate Art", "do": "Chaos", "tg": "Champion Unit\nTeemo\nBandle City\nYordle", "fo": true, "tn": false, "me": false, "nn": true, "bm": false, "pw": false, "pt": "", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/teemo-scout-gg-ez-en-item-10660.webp", "inf": "Foil Nexus Night promo with the \"GG EZ\" background art (OGN 197b/298). Not the same card as the plain Teemo - Scout store promo."}$j$::jsonb || jsonb_build_object('st', coalesce((select data->>'st' from promo_items where upper(data->>'st')='NEED' limit 1),'NEED'))
where not exists (select 1 from promo_items where id = 'item-10660');
insert into promo_items (id, r, data)
select 'item-10661', 10661, $j${"r": 10661, "id": "item-10661", "cat": "PROMO", "nm": "Teemo - Scout (GG EZ)", "la": "Korean", "ev": "NN - Korea", "se": "OGN", "ty": "Card", "cn": "197b", "ra": "Overnumber/Alternate Art", "do": "Chaos", "tg": "Champion Unit\nTeemo\nBandle City\nYordle", "fo": true, "tn": false, "me": false, "nn": true, "bm": false, "pw": false, "pt": "", "img": "https://cdn.jsdelivr.net/gh/unravelingtherift/collect-bound-data@main/promo-images/teemo-scout-gg-ez-kr-item-10661.webp", "inf": "Foil Nexus Night promo with the \"GG EZ\" background art (OGN 197b/298). Not the same card as the plain Teemo - Scout store promo."}$j$::jsonb || jsonb_build_object('st', coalesce((select data->>'st' from promo_items where upper(data->>'st')='NEED' limit 1),'NEED'))
where not exists (select 1 from promo_items where id = 'item-10661');
